document.addEventListener('click',e=>{const a=e.target.closest('[data-action="add-member"]');if(!a)return;e.preventDefault();e.stopImmediatePropagation();openModal(`<div class="eyebrow">NEW FAMILY PROFILE</div><h2>Add a family member</h2><label class="mv-field">Full name<input id="mvNewMemberName" required></label><label class="mv-field">Relationship<select id="mvNewMemberRelation"><option>Spouse</option><option>Child</option><option>Parent</option><option>Sibling</option><option>Other family</option></select></label><div class="mv-modal-actions"><button type="button" class="btn" data-dismiss>Cancel</button><button type="button" class="btn btn-primary" id="mvSaveMember">Add profile</button></div>`);document.getElementById('mvSaveMember').onclick=()=>{const name=document.getElementById('mvNewMemberName').value.trim();if(!name){document.getElementById('mvNewMemberName').focus();return}const parts=name.split(/\s+/);members.push({id:`member-${Date.now()}`,name,relation:document.getElementById('mvNewMemberRelation').value,initials:parts.slice(0,2).map(x=>x[0].toUpperCase()).join(''),tone:'avatar-blue',docs:0,last:'No records yet'});closeModal();render('family');notify(`${name} added to this local preview.`)}},true);
