const mvCardHead=(title,sub,right='')=>`<div class="card-head"><div><h3>${title}</h3><p>${sub}</p></div>${right}</div>`;
function mvRecordRows(list){return list.length?`<div class="doc-list">${list.map(d=>`<button class="doc-row mv-doc-row" data-mv-doc="${mvSafe(d.id)}"><span class="doc-type ${mvSafe(d.tone||'')}">${mvSafe(d.icon||'▤')}</span><span class="doc-info"><strong>${mvSafe(d.title)}</strong><small>${mvSafe(d.type)} · ${mvSafe(mvDateLabel(mvIsoDate(d.date)))} · ${mvSafe(mvMember(d.memberId).name)}</small></span>${statusBadge(d.status)}${d.demo?'<span class="mv-sample-tag">SAMPLE</span>':''}</button>`).join('')}</div>`:`<div class="mv-empty"><strong>No records yet</strong><p>Add a record to keep this person’s care information together.</p><button class="btn btn-primary" data-mv-upload="${mvSafe(mvSelectedMember)}">＋ Add a record</button></div>`}
function mvHeader(kicker,title,description,action=''){return `<div class="row-between"><div><div class="eyebrow">${kicker}</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${description}</p></div>${action}</div>`}
function mvWellness(m){const own=docs.filter(d=>d.memberId===m.id);return `<section class="mv-wellness card"><div><div class="eyebrow">RECORD COVERAGE · ${mvSafe(m.name.toUpperCase())}</div><h2>${own.length?`${own.length} record${own.length===1?'':'s'} linked to this profile`:'Not enough information yet'}</h2><p>This indicates only how many records have been added to MediVault. It is not a health score, diagnosis, or treatment recommendation.</p><span class="mv-disclaimer">“This wellness summary is generated from your records and is not a medical diagnosis or substitute for professional care.”</span></div><div class="mv-ring" aria-label="${own.length} records linked">${own.length}</div></section>`}
function mvDashboard(){const today=mvToday(), upcoming=meds.filter(m=>!m.memberId||members.some(p=>p.id===m.memberId)).length;return `${mvHeader('FAMILY HEALTH VAULT',`Welcome, ${mvSafe(mvMember('aarav').name.split(' ')[0])}`,'Your family’s health information, organized in one place.')}
  <section class="mv-welcome mv-upload-hero"><div class="mv-upload-hero__content"><span class="mv-upload-hero__icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M7 3.75h6.25L18 8.5v11.75H7a2 2 0 0 1-2-2v-12.5a2 2 0 0 1 2-2Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/><path d="M13 4v5h5M8.75 13h5.5M8.75 16.5h3.25" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/><path d="M17.5 12v5m-2.5-2.5h5" stroke="#16A34A" stroke-width="1.7" stroke-linecap="round"/></svg></span><div class="mv-upload-hero__copy"><div class="eyebrow">MEDIVAULT · YOUR FAMILY HEALTH</div><h2>Care feels simpler when it’s together.</h2><p>Keep records, medication notes, and care plans connected to the right family member.</p></div></div><button class="btn btn-primary mv-upload-cta" data-action="upload"><svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false"><path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg><span>Add medical record</span></button></section>
  <div class="mv-stat-grid"><article class="mv-stat"><span>Family members</span><strong>${members.length}</strong><small>Care circle</small></article><article class="mv-stat"><span>Health records</span><strong>${docs.length}</strong><small>Fictional sample and local uploads</small></article><article class="mv-stat"><span>Medication reminders</span><strong>${upcoming}</strong><small>Across family profiles</small></article></div>
  <div class="mv-dashboard-grid"><section class="card">${mvCardHead('Your family','Choose a person to open their medical history',`<button class="text-link" data-view="family">All members →</button>`)}<div class="mv-member-list">${members.map(m=>`<button class="mv-member-card" data-mv-profile="${m.id}"><span class="avatar ${m.tone}">${mvSafe(m.initials)}</span><span><strong>${mvSafe(m.name)}</strong><small>${mvSafe(m.relation)} · ${m.docs} records</small></span><b>Open history →</b></button>`).join('')}</div></section><section class="card">${mvCardHead('Recent activity','Most recent records across your family',`<button class="text-link" data-view="vault">Choose a person →</button>`)}${mvRecordRows([...docs].sort((a,b)=>mvIsoDate(b.date).localeCompare(mvIsoDate(a.date))).slice(0,3))}</section></div><p class="mv-demo-note">Sample records are fictional. Medication information is for demonstration only; follow your clinician’s instructions.</p>`}
function mvFamily(){return `${mvHeader('YOUR CARE CIRCLE','Family members','Open a profile to see only that person’s records, medications, and activity.',`<button class="btn btn-primary" data-action="add-member">＋ Add member</button>`)}<div class="mv-family-grid">${members.map(m=>`<article class="card mv-family-card"><div class="person-head"><span class="avatar ${m.tone}">${mvSafe(m.initials)}</span><div><strong>${mvSafe(m.name)}</strong><small>${mvSafe(m.relation)}</small></div></div><div class="mv-profile-summary"><div><small>Records</small><strong>${m.docs}</strong></div><div><small>Medication reminders</small><strong>${meds.filter(x=>x.memberId===m.id).length}</strong></div></div><button class="btn btn-secondary btn-full" data-mv-profile="${m.id}">Open health profile →</button></article>`).join('')}</div>`}
function mvProfile(){const m=mvMember(mvProfileId);const ownDocs=docs.filter(d=>d.memberId===m.id), ownMeds=meds.filter(x=>x.memberId===m.id);return `${mvHeader('FAMILY PROFILE',mvSafe(m.name),`${mvSafe(m.relation)} · This view contains information linked to this profile.`,`<button class="btn btn-secondary" data-view="family">← Family members</button>`)}${mvWellness(m)}<section class="mv-profile-actions"><button class="btn btn-primary" data-mv-upload="${m.id}">＋ Add a record for ${mvSafe(m.name.split(' ')[0])}</button><button class="btn btn-secondary" data-mv-open-vault="${m.id}">Open full vault for ${mvSafe(m.name.split(' ')[0])}</button><button class="btn btn-secondary" data-mv-open-meds="${m.id}">Medication calendar</button></section><div class="mv-profile-grid"><section class="card">${mvCardHead('Health records',`${ownDocs.length} linked records`)}${mvRecordRows(ownDocs)}</section><section class="card">${mvCardHead('Medication reminders',`${ownMeds.length} reminders for this person`)}${ownMeds.length?`<div class="mv-list">${ownMeds.map(x=>`<div class="mv-list-row"><span class="mv-med-icon">✚</span><span><strong>${mvSafe(x.name)}</strong><small>${mvSafe(x.detail)}</small></span><b>${mvSafe(x.time)}</b></div>`).join('')}</div>`:'<div class="mv-empty"><p>No medication reminders are linked to this profile.</p></div>'}</section></div><section class="card mv-profile-timeline">${mvCardHead('Activity','Records and care linked to this profile')}${mvRecordRows([...ownDocs].sort((a,b)=>mvIsoDate(b.date).localeCompare(mvIsoDate(a.date))))}</section>`}
function mvVault(){const member=mvVaultFilter==='all'?'all':mvVaultFilter;return `${mvHeader('YOUR RECORDS','Medical vault','Search and filter records by person, category, and date.',`<button class="btn btn-primary" data-action="upload">＋ Add a record</button>`)}<div class="mv-filters"><label>Search<input id="mvVaultSearch" type="search" placeholder="Name, title, category…"></label><label>Family member<select id="mvPersonFilter">${mvMemberOptions(member)}</select></label><label>Category<select id="mvCategoryFilter"><option value="all">All categories</option>${['Report','Prescription','Lab report','Vaccination','Visit summary','Medical bill'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>From<input id="mvFromDate" type="date"></label><label>To<input id="mvToDate" type="date"></label><button class="btn btn-secondary" id="mvSort">Date: newest first</button><button class="btn btn-secondary" id="mvClear">Clear filters</button></div><div class="mv-results-meta"><span id="mvVaultCount">${docs.length} records</span><span>All records are fictional preview data.</span></div><div id="mvVaultResults">${mvRecordRows([...docs].sort((a,b)=>mvIsoDate(b.date).localeCompare(mvIsoDate(a.date))))}</div>`}
function mvTimeline(){const sorted=[...docs].sort((a,b)=>mvIsoDate(b.date).localeCompare(mvIsoDate(a.date)));return `${mvHeader('HEALTH HISTORY','Family timeline','Choose a person or view family-wide activity. Events link to their source records.') }<div class="mv-filters mv-timeline-filters"><label>Family member<select id="mvTimelinePerson">${mvMemberOptions(mvTimelineMember)}</select></label><label>From<input id="mvTimelineFrom" type="date"></label><label>To<input id="mvTimelineTo" type="date"></label><label>Activity type<select id="mvTimelineType"><option value="all">All activity</option><option value="records">Records</option><option value="medications">Medication dose logs</option><option value="bookings">Demo bookings</option></select></label></div><div id="mvTimelineResults">${mvTimelineRows(sorted,mvTimelineMember,'','','all')}</div>`}
function mvTimelineRows(records,person,from,to,type){const events=[];for(const d of records){const dt=mvIsoDate(d.date);if((person==='all'||person===d.memberId)&&(!from||dt>=from)&&(!to||dt<=to)&&(type==='all'||type==='records'))events.push({id:d.id,date:dt,label:d.demo?'Historical sample record':'Record added',title:d.title,person:d.memberId,icon:'▤'})}for(const a of mvAudit){if((person==='all'||person===a.member)&&(!from||a.date>=from)&&(!to||a.date<=to)&&(type==='all'||type==='medications'))events.push({date:a.date,label:'Medication dose logged',title:`${a.name} marked ${a.status}`,person:a.member,icon:'✚'})}for(const b of mvAppointments){if((person==='all'||person===b.memberId)&&(!from||b.date>=from)&&(!to||b.date<=to)&&(type==='all'||type==='bookings'))events.push({date:b.date,label:'Demo appointment',title:`${b.test} · ${b.provider}`,person:b.memberId,icon:'＋'})}events.sort((a,b)=>b.date.localeCompare(a.date));if(!events.length)return '<div class="mv-empty"><strong>No activity in this range</strong><p>Adjust the filters or add a record.</p></div>';let year='';return `<div class="mv-timeline">${events.map(e=>{const y=e.date.slice(0,4),header=y!==year?`<h4 class="mv-event-year">${year=y}</h4>`:'';return `${header}<article class="mv-event"><span>${e.icon}</span><div><small>${mvSafe(mvDateLabel(e.date))} · ${mvSafe(e.label)} · ${mvSafe(mvMember(e.person).name)}</small>${e.id?`<button class="mv-event-link" data-mv-doc="${mvSafe(e.id)}">${mvSafe(e.title)} →</button>`:`<strong>${mvSafe(e.title)}</strong>`}</div></article>`}).join('')}</div>`}
const mvCategories=['Diagnosis / illness','Hospitalization / discharge','Prescription / medication','Laboratory report','Imaging / diagnostic report','Vaccination','Allergies','Doctor visit / follow-up','Other medical document'];
mvVault=function(){return `${mvHeader('MEDICAL VAULT','Choose a family member','Select a profile to open their records and medical history.')}<div class="mv-patient-picker">${members.map(m=>{const latest=docs.filter(d=>d.memberId===m.id).sort((a,b)=>mvIsoDate(b.date).localeCompare(mvIsoDate(a.date)))[0];return `<article class="card mv-patient-card"><div class="person-head"><span class="avatar ${m.tone}">${mvSafe(m.initials)}</span><div><strong>${mvSafe(m.name)}</strong><small>${mvSafe(m.relation)}</small></div></div><div class="mv-patient-meta"><span>${docs.filter(d=>d.memberId===m.id).length} records</span><span>${latest?`Latest: ${mvSafe(latest.title)} · ${mvSafe(mvDateLabel(mvIsoDate(latest.date)))}`:'No records yet'}</span></div><button class="btn btn-secondary btn-full" data-mv-profile="${mvSafe(m.id)}">Open medical history →</button></article>`}).join('')}</div><p class="mv-demo-note">All sample records are fictional and are not medical information.</p>`};
const mvBaseVault=mvVault;
mvVault=function(){return mvBaseVault().replace('<div class="mv-patient-picker">','<label class="mv-patient-search">Search family members or record titles<input id="mvVaultPatientSearch" type="search" placeholder="Search by name or a record title"></label><div class="mv-patient-picker">')};
function mvFilterPatientPicker(){const q=(document.getElementById('mvVaultPatientSearch')?.value||'').trim().toLowerCase();document.querySelectorAll('.mv-patient-card').forEach(card=>{const id=card.querySelector('[data-mv-profile]')?.dataset.mvProfile,m=members.find(x=>x.id===id),records=docs.filter(d=>d.memberId===id),hay=`${m?.name||''} ${m?.relation||''} ${records.map(d=>d.title).join(' ')}`.toLowerCase();card.hidden=!!q&&!hay.includes(q)});const any=[...document.querySelectorAll('.mv-patient-card')].some(x=>!x.hidden);let empty=document.getElementById('mvPatientPickerEmpty');if(!any){if(!empty){empty=document.createElement('p');empty.id='mvPatientPickerEmpty';empty.className='mv-empty';empty.textContent='No family members or record titles match that search.';document.querySelector('.mv-patient-picker')?.after(empty)}}else empty?.remove()}
mvProfile=function(){const m=mvMember(mvProfileId);mvSelectedMember=m.id;const ownDocs=docs.filter(d=>d.memberId===m.id).sort((a,b)=>mvIsoDate(b.date).localeCompare(mvIsoDate(a.date)));const groups=[...new Set(ownDocs.map(d=>mvIsoDate(d.date).slice(0,4)))];return `${mvHeader('MEDICAL HISTORY',mvSafe(m.name),`${mvSafe(m.relation)} · ${ownDocs.length} records linked to this profile.`,`<button class="btn btn-secondary" data-view="vault">← Choose another person</button>`)}<div class="mv-profile-actions"><button class="btn btn-primary" data-mv-upload="${mvSafe(m.id)}">＋ Add record</button><button class="btn btn-secondary" data-mv-share="${mvSafe(m.id)}">Share medical history</button><button class="btn btn-secondary" data-mv-open-timeline="${mvSafe(m.id)}">Timeline</button><button class="btn btn-secondary" data-mv-open-meds="${mvSafe(m.id)}">Medications</button></div>${mvWellness(m)}<div class="mv-filters"><label>Search records<input id="mvPatientSearch" type="search" placeholder="Search this person's history"></label><label>Category<select id="mvPatientCategory"><option value="all">All categories</option>${mvCategories.map(c=>`<option>${mvSafe(c)}</option>`).join('')}</select></label><label>From date<input id="mvPatientFrom" type="date"></label><label>To date<input id="mvPatientTo" type="date"></label><button type="button" class="btn btn-secondary" id="mvPatientClear">Clear filters</button></div><section class="card mv-history-card"><div class="card-head"><div><h3>Chronological medical history</h3><p>Only records associated with ${mvSafe(m.name)} are shown. Select a record for details and source information.</p></div></div><div id="mvPatientResults">${groups.map(year=>`<section class="mv-history-year"><h4>${year}</h4>${mvRecordRows(ownDocs.filter(d=>mvIsoDate(d.date).startsWith(year)))}</section>`).join('')||'<div class="mv-empty"><strong>No medical history yet</strong><p>No records have been added for this profile. Nothing is inferred.</p></div>'}</div></section><p class="mv-demo-note">Sample records are fictional. Extracted or sample text marked “Needs review” is unverified. No OCR is running in this prototype.</p>`};
const mvBaseProfile=mvProfile;
function mvActiveShares(memberId){const active=[...mvShares.entries()].filter(([,s])=>s.memberId===memberId&&!s.revoked&&s.expiresAt>Date.now());if(!active.length)return '';return `<section class="card mv-active-shares"><h3>Active demo shares</h3>${active.map(([token,s])=>`<div class="mv-share-row"><span><strong>${s.scope==='full'?'Full history':'Emergency summary'}</strong><small>Expires ${mvSafe(new Date(s.expiresAt).toLocaleString())}</small></span><button class="btn btn-secondary" data-mv-show-share="${token}">Show QR</button><button class="btn btn-destructive" data-mv-revoke="${token}">Revoke</button></div>`).join('')}</section>`}
mvProfile=function(){return mvBaseProfile().replace('<div class="mv-profile-actions">',`${mvActiveShares(mvProfileId)}<div class="mv-profile-actions">`)};
function mvIsoDate(s){const d=new Date(s);return isNaN(d)?'':d.toISOString().slice(0,10)}
function mvMedStatus(member,med,date){const logged=mvDoseLog[mvKey(member,med.id,date)];if(logged)return logged.status;if(date<mvToday())return 'Not recorded';if(date>mvToday())return 'Upcoming';const [h,min]=med.time.split(':').map(Number);const due=new Date();due.setHours(h,min+120,0,0);return Date.now()>due.getTime()?'Missed':'Upcoming'}
function mvMedCalendar(){const y=mvCalendarDate.getFullYear(),mo=mvCalendarDate.getMonth(),first=new Date(y,mo,1),offset=(first.getDay()+6)%7,days=new Date(y,mo+1,0).getDate(),cells=Array(offset).fill('<span class="mv-day mv-day-empty"></span>');for(let n=1;n<=days;n++){const date=new Date(y,mo,n),iso=`${y}-${String(mo+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`,hasLog=meds.some(m=>m.memberId===mvSelectedMember&&mvDoseLog[mvKey(mvSelectedMember,m.id,iso)]);cells.push(`<button class="mv-day ${iso===mvLocalIso(mvMedicationDate)?'selected':''} ${hasLog?'has-log':''}" data-mv-date="${iso}" aria-label="${mvDateLabel(iso)}">${n}${hasLog?'<i></i>':''}</button>`)}return `<div class="mv-calendar"><div class="mv-calendar-head"><button class="btn btn-secondary" data-mv-month="-1" aria-label="Previous month">‹</button><strong>${mvCalendarDate.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</strong><button class="btn btn-secondary" data-mv-month="1" aria-label="Next month">›</button></div><div class="mv-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<span>${x}</span>`).join('')}</div><div class="mv-days">${cells.join('')}</div></div>`}
function mvMedications(){const member=mvMember(mvSelectedMember),day=mvLocalIso(mvMedicationDate),list=meds.filter(m=>m.memberId===member.id);return `${mvHeader('DAILY CARE','Medication calendar','Track a dose only when you know what happened. No schedule is medical advice.') }<div class="mv-filters"><label>Family member<select id="mvMedicationMember">${members.map(m=>`<option value="${m.id}" ${m.id===member.id?'selected':''}>${mvSafe(m.name)}</option>`).join('')}</select></label><label>Selected date<input id="mvDoseDate" type="date" value="${day}"></label><button class="btn btn-primary" data-action="add-med">＋ Add reminder</button></div><div class="mv-med-layout"><section class="card">${mvMedCalendar()}<div class="mv-legend"><span>● Selected day</span><span>• Has a saved dose log</span></div></section><section class="card">${mvCardHead(`${mvSafe(member.name)} · ${mvDateLabel(day)}`,'Choose Taken, Skipped, or leave this dose unrecorded.')}${list.length?`<div class="mv-dose-list">${list.map(m=>{const status=mvMedStatus(member.id,m,day);return `<article class="mv-dose"><div><strong>${mvSafe(m.name)}</strong><small>${mvSafe(m.detail)} · ${mvSafe(m.time)}</small><span class="mv-dose-status status-${status.toLowerCase().replace(' ','-')}">${status}</span></div><div class="mv-dose-actions"><button class="btn btn-secondary" data-mv-dose="${m.id}" data-status="Taken">Taken</button><button class="btn btn-secondary" data-mv-dose="${m.id}" data-status="Skipped">Skipped</button></div></article>`}).join('')}</div>`:'<div class="mv-empty"><strong>No medication reminders</strong><p>Add a reminder and assign it to this family member.</p></div>'}<p class="mv-demo-note">For today, “Missed” is shown only after the scheduled time plus a two-hour grace period, and only when no status is logged. Past dates without a log say “Not recorded.”</p></section></div><section class="card mv-audit"><h3>Recent dose changes</h3>${mvAudit.filter(a=>a.member===member.id).slice(-8).reverse().map(a=>`<p>${mvSafe(a.date)} · ${mvSafe(a.name)} marked ${mvSafe(a.status)} at ${mvSafe(a.time)}</p>`).join('')||'<p>No dose changes recorded for this profile.</p>'}</section>`}
function mvLabs(){return `${mvHeader('CARE & TESTING','Labs & care','Explore clearly labeled demonstration listings and create a local, non-booking preview.') }<div class="mv-labs-layout"><section class="card"><h2>Find a diagnostic test</h2><p class="page-subtitle">Common test names; provider availability is not connected.</p><label class="mv-field">Family member<select id="mvLabMember">${members.map(m=>`<option value="${m.id}">${mvSafe(m.name)}</option>`).join('')}</select></label><div class="mv-test-grid">${mvTests.map((t,i)=>`<button class="mv-test ${i===0?'selected':''}" data-mv-test="${mvSafe(t)}">${mvSafe(t)} <span>›</span></button>`).join('')}</div><div class="mv-location"><label class="mv-field">City, locality, or PIN<input id="mvLocation" placeholder="e.g. Pune, Baner or 411045"></label><button class="btn btn-secondary" id="mvLocationButton">Use my location</button></div><p class="mv-location-status" id="mvLocationStatus" aria-live="polite">Enter a location to browse sample listings.</p><button class="btn btn-primary" id="mvFindProviders">Show demo listings</button><div class="mv-provider-list" id="mvProviders"></div></section><aside class="card"><h3>What this preview means</h3><p class="page-subtitle">Listings below are fictional examples. Prices in INR are illustrative. No providers, lab slots, or appointments are connected.</p><div class="mv-care-note">For test selection and interpretation, follow advice from a qualified clinician.</div><h3>Demo appointment history</h3>${mvAppointments.length?mvAppointments.map(a=>`<p>${mvDateLabel(a.date)} · ${mvSafe(a.test)} · ${mvSafe(mvMember(a.memberId).name)}</p>`).join(''):'<p class="page-subtitle">No demo appointments created.</p>'}</aside></div>`}
function mvAuth(){return `${mvHeader('ACCOUNT ACCESS','Sign in to MediVault','The account interface is a local preview; no authentication service is configured.') }<div class="mv-auth card"><div class="mv-auth-tabs"><button class="selected" data-mv-auth-mode="signin">Sign in</button><button data-mv-auth-mode="signup">Create account</button></div><form id="mvAuthForm"><label>Email address<input type="email" id="mvEmail" autocomplete="email" required placeholder="you@example.com"></label><label>Password<span class="mv-password"><input type="password" id="mvPassword" autocomplete="current-password" minlength="8" required><button type="button" id="mvTogglePassword" aria-label="Show password">Show</button></span></label><button class="text-link" type="button" id="mvForgot">Forgot password?</button><button class="btn btn-primary btn-full" type="submit">Continue</button></form><div class="mv-auth-separator">or</div><button type="button" class="btn btn-secondary btn-full" id="mvGoogle">Continue with Google</button><div class="mv-config-note"><strong>Authentication is not connected</strong><p>To enable sign-in, connect a Supabase project, set its URL and publishable key, and configure Google OAuth and allowed redirect URLs. This demo will not create a session or claim a successful login.</p></div><p class="mv-demo-note">By continuing, you acknowledge this local demonstration does not create an account or store credentials.</p></div>`}
function mvSettings(){return `${mvHeader('PREFERENCES','Settings','Manage the local preview and find account connection options.') }<div class="mv-settings-grid"><section class="card"><h3>Account</h3><p class="page-subtitle">Signed out · Demo preview</p><button class="btn btn-secondary" data-view="auth">Sign in or create an account</button></section><section class="card"><h3>Privacy and storage</h3><p class="page-subtitle">Sample information and new records exist only in this browser session. No cloud backup or secure account storage is configured.</p><p>Camera and location permissions are requested only after selecting their controls.</p></section></div>`}
function mvEmergency(){return `${mvHeader('QUICK ACCESS','Emergency information','A simple local page for organizing emergency details. Confirm all information with the family.') }<section class="card mv-emergency"><p>No emergency contacts have been added to this demo.</p><button class="btn btn-primary" data-action="add-member">Review family members</button><p class="mv-demo-note">This prototype does not provide emergency services. In an emergency, contact your local emergency number.</p></section>`}
function mvLanding(){return `${mvHeader('MEDIVAULT','Family health, together','A private place to organize health information for the people you care about.') }<section class="mv-welcome"><div><h2>Keep the important details close.</h2><p>Records, medication notes, and care history organized by family member.</p></div><button class="btn btn-primary" data-view="auth">Sign in / Create account</button></section><button class="btn btn-secondary" data-view="overview">Explore the local demo</button>`}
function finishRecord(){const title=document.getElementById('reviewTitle')?.value.trim();if(!title){document.getElementById('reviewTitle')?.focus();notify('Add a title for this record first.');return}const memberId=document.getElementById('reviewWho')?.value,member=members.find(m=>m.id===memberId);if(!member){notify('Choose a family member before saving this record.');return}const category=document.getElementById('reviewCategory').value,date=document.getElementById('reviewDate')?.value||mvToday();if(date>mvToday()){notify('The document date cannot be in the future.');return}const first=uploadSession.pages[0],files=uploadSession.pages.map(p=>({name:p.name||'Uploaded page',type:p.file?.type||'image/jpeg',url:p.url||URL.createObjectURL(p.file)}));docs.unshift({id:`record-${crypto.randomUUID?.()||Date.now()}`,memberId:member.id,title,type:category,date,status:'Needs review',summary:document.getElementById('reviewNotes')?.value.trim()||'No notes added.',notes:document.getElementById('reviewNotes')?.value.trim()||'',findings:'',reviewState:'User-entered; review required',icon:category.includes('Prescription')?'✳':category.includes('Laboratory')?'⌁':category==='Vaccination'?'＋':'▤',tone:category.includes('Laboratory')?'labs':category==='Vaccination'?'vaccine':'',source:first?.name||'User upload',originalName:first?.name||'',files,demo:false});member.docs++;member.last=`${category} · ${mvDateLabel(date)}`;member.lastDate=date;stopCamera();uploadSession.pages=[];delete uploadSession.mvMemberId;delete uploadSession.forcedMemberId;uploadSession.memberId=member.id;closeModal();render(activeView==='landing'?'vault':activeView);notify(`Record added locally to ${member.name} · Needs review.`)}
function render(view){if(view?.startsWith('family-profile:')){mvProfileId=view.split(':')[1];view='family-profile';}activeView=view;const titles={overview:'Overview',family:'Family members',vault:'Medical vault',timeline:'Health timeline',medications:'Medication calendar',emergency:'Emergency information',labs:'Labs & care',settings:'Settings',auth:'Account access',landing:'MediVault', 'family-profile':mvMember(mvProfileId).name};document.getElementById('currentCrumb').textContent=titles[view]||'Overview';document.querySelectorAll('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('.crumb span').textContent=view==='landing'?'MediVault':'My workspace';const counts=document.querySelectorAll('.sidebar .nav-count');if(counts[0])counts[0].textContent=members.length;if(counts[1])counts[1].textContent=docs.length;content.innerHTML=({overview:mvDashboard,family:mvFamily,'family-profile':mvProfile,vault:mvVault,timeline:mvTimeline,medications:mvMedications,labs:mvLabs,emergency:mvEmergency,settings:mvSettings,auth:mvAuth,landing:mvLanding}[view]||mvDashboard)();window.scrollTo({top:0,behavior:'smooth'});}
function mvOpenProfile(id){if(!members.some(m=>m.id===id))return;mvProfileId=id;mvSelectedMember=id;const pending=mvPendingPatientSearch;mvPendingPatientSearch='';render('family-profile:'+id);const m=mvMember(id);if(pending&&!m.name.toLowerCase().includes(pending.toLowerCase())){const input=document.getElementById('mvPatientSearch');if(input){input.value=pending;mvFilterPatient()}}}
function mvOpenTimeline(id){mvTimelineMember=members.some(m=>m.id===id)?id:'all';if(mvTimelineMember!=='all')mvSelectedMember=mvTimelineMember;render('timeline')}
