function mvFilterPatient(){const person=mvSelectedMember,q=(document.getElementById('mvPatientSearch')?.value||'').trim().toLowerCase(),cat=document.getElementById('mvPatientCategory')?.value||'all',from=document.getElementById('mvPatientFrom')?.value||'',to=document.getElementById('mvPatientTo')?.value||'';const own=docs.filter(d=>d.memberId===person&&(cat==='all'||d.type===cat)&&(!q||`${d.title} ${d.type} ${d.summary||''} ${d.notes||''}`.toLowerCase().includes(q))&&(!from||mvIsoDate(d.date)>=from)&&(!to||mvIsoDate(d.date)<=to)).sort((a,b)=>mvIsoDate(b.date).localeCompare(mvIsoDate(a.date)));const years=[...new Set(own.map(d=>mvIsoDate(d.date).slice(0,4)))];document.getElementById('mvPatientResults').innerHTML=own.length?years.map(y=>`<section class="mv-history-year"><h4>${y}</h4>${mvRecordRows(own.filter(d=>mvIsoDate(d.date).startsWith(y)))}</section>`).join(''):'<div class="mv-empty"><strong>No matching records</strong><p>No records for this person match those filters.</p></div>'}
const mvBaseShowUpload=showUpload;
