function mvShowDoc(id,shareToken=''){const d=docs.find(x=>x.id===id);if(!d)return;if(shareToken){const share=mvShares.get(shareToken);if(!share||share.revoked||share.expiresAt<=Date.now()||!share.recordIds.includes(d.id)){mvRenderDoctorShare(shareToken);return}}const m=mvMember(d.memberId);const fileViews=(d.files||[]).map(f=>f.type?.startsWith('image/')?`<img class="mv-original-preview" src="${f.url}" alt="Original image: ${mvSafe(f.name)}">`:`<div class="mv-file-preview"><strong>${mvSafe(f.name)}</strong><a href="${f.url}" target="_blank" rel="noopener">Open original PDF</a></div>`).join('');openModal(`<div class="eyebrow">${mvSafe(d.type)} · ${mvSafe(mvDateLabel(mvIsoDate(d.date)))}</div><h2>${mvSafe(d.title)}</h2><p class="modal-description">Patient: ${mvSafe(m.name)} · Status: ${mvSafe(d.status)} · ${d.demo?'FICTIONAL SAMPLE RECORD':'Added to this browser session'}</p><section class="mv-detail-panel"><strong>Record information</strong><p>${mvSafe(d.summary||d.notes||'No additional information was entered.')}</p>${d.findings?`<p>${mvSafe(d.findings)}</p>`:''}<small>Source: ${mvSafe(d.source||d.originalName||'User-added record')} · ${mvSafe(d.reviewState||'User-entered; not independently verified')}</small></section>${fileViews||`<div class="mv-file-preview"><strong>${d.demo?'No original document attached to this fictional sample.':'No original preview is available.'}</strong></div>`}<div class="mv-modal-actions"><button class="btn" type="button" data-dismiss>Close</button>${!shareToken?'<button class="btn btn-destructive" id="mvDeleteDoc">Remove record</button>':''}</div>`);const del=document.getElementById('mvDeleteDoc');if(del)del.onclick=()=>{docs=docs.filter(x=>x.id!==d.id);const owner=mvMember(d.memberId);owner.docs=Math.max(0,owner.docs-1);closeModal();render(activeView);notify('Record removed from this preview.')};}
