function mvShareDialog(memberId){const m=mvMember(memberId);openModal(`<div class="eyebrow">LOCAL DEMO SHARING</div><h2>Share ${mvSafe(m.name)}’s medical history</h2><p class="modal-description">Choose a scope and expiry. Review the exact records before creating a demo link.</p><label class="mv-field">Access scope<select id="mvShareScope"><option value="full">Full medical history</option><option value="emergency">Emergency summary</option></select></label><label class="mv-field">Link expiry<select id="mvShareExpiry"><option value="1">1 hour</option><option value="24" selected>24 hours</option><option value="168">7 days</option></select></label><div class="mv-share-preview" id="mvSharePreview"></div><div class="mv-share-warning"><strong>Demo only — not secure sharing</strong><p>This browser-only prototype has no server authorization, private storage, rate limiting, or cross-device revocation. Do not use real patient data.</p></div><div class="mv-modal-actions"><button class="btn" type="button" data-dismiss>Cancel</button><button class="btn btn-primary" type="button" id="mvCreateShare">Create demo access</button></div>`);const paint=()=>{const scope=document.getElementById('mvShareScope').value,selected=mvShareRecords(memberId,scope),label=scope==='full'?'All available records for this person':'Emergency-relevant records only: allergies, diagnoses, prescriptions, and hospital discharge notes';document.getElementById('mvSharePreview').innerHTML=`<strong>Information included (${selected.length} records)</strong><p>${mvSafe(label)}</p>${selected.length?`<ul>${selected.map(d=>`<li>${mvSafe(d.title)} · ${mvSafe(d.type)} · ${mvSafe(mvDateLabel(mvIsoDate(d.date)))}</li>`).join('')}</ul>`:'<p>No records match this scope yet.</p>'}`};document.getElementById('mvShareScope').addEventListener('change',paint);paint();document.getElementById('mvCreateShare').onclick=()=>{const scope=document.getElementById('mvShareScope').value,recordIds=mvShareRecords(memberId,scope).map(d=>d.id);if(!recordIds.length){notify('There are no records in this share scope.');return}let token;try{token=mvMakeToken()}catch(err){notify(err.message);return}const hours=Number(document.getElementById('mvShareExpiry').value),share={memberId,scope,recordIds,expiresAt:Date.now()+hours*3600000,revoked:false,createdAt:Date.now()};mvShares.set(token,share);mvShareAudit.push({action:'created',at:Date.now()});mvShowCreatedShare(token)}}
function mvShareRecords(memberId,scope){const own=docs.filter(d=>d.memberId===memberId);if(scope==='full')return own;return own.filter(d=>['Allergies','Diagnosis / illness','Prescription / medication','Hospitalization / discharge'].includes(d.type))}
function mvShowCreatedShare(token){const share=mvShares.get(token),m=mvMember(share.memberId),url=new URL(location.href);url.hash=`doctor-share/${token}`;url.search="";const href=url.href;let svg='';try{svg=mvQrSvg(href)}catch(err){notify(err.message)}openModal(`<div class="eyebrow">DEMO LINK CREATED</div><h2>${mvSafe(m.name)} · ${share.scope==='full'?'Full history':'Emergency summary'}</h2><p class="modal-description">Expires ${mvSafe(new Date(share.expiresAt).toLocaleString())}. Opaque token only; the URL does not contain medical information.</p><div class="mv-qr-preview">${svg||'<p>Could not render this URL as a QR code.</p>'}</div><label class="mv-field">Demo share URL<input id="mvShareUrl" readonly value="${mvSafe(href)}"></label><p class="mv-demo-note">Local session demo: the link can be opened only in this same app session. It is not protected by a server and must not be used for real records.</p><div class="mv-modal-actions"><button class="btn" type="button" data-dismiss>Close</button><button class="btn btn-secondary" type="button" id="mvCopyShare">Copy link</button><button class="btn btn-secondary" type="button" data-mv-doctor-preview="${token}">Open doctor preview</button><button class="btn btn-destructive" type="button" data-mv-revoke="${token}">Revoke access</button></div>`);document.getElementById('mvCopyShare').onclick=async()=>{try{await navigator.clipboard.writeText(href);notify('Demo link copied.')}catch{const f=document.getElementById('mvShareUrl');f.select();notify('Select and copy the demo link.')}}}
function mvRenderDoctorShare(token){mvDoctorShareId=token;const share=mvShares.get(token);if(!share||share.revoked||share.expiresAt<=Date.now()){document.title='Share unavailable · MediVault';document.querySelector('meta[name="robots"]')?.setAttribute('content','noindex,nofollow');content.innerHTML=`<section class="card mv-doctor-page"><div class="eyebrow">MEDIVAULT · DOCTOR VIEW</div><h1>This demo share is unavailable</h1><p>It may have expired, been revoked, or opened in a different browser session.</p><p>This link does not provide server-secured access.</p><button class="btn btn-secondary" data-view="overview">Return to MediVault</button></section>`;return}const m=mvMember(share.memberId),records=share.recordIds.map(id=>docs.find(d=>d.id===id)).filter(d=>d&&d.memberId===share.memberId);document.title=`Shared history · MediVault`;let robot=document.querySelector('meta[name="robots"]');if(!robot){robot=document.createElement('meta');robot.name='robots';document.head.append(robot)}robot.content='noindex,nofollow';content.innerHTML=`<main class="mv-doctor-page"><div class="mv-doctor-notice"><strong>Local demo share · Read-only preview</strong><span>Not a secure or server-authorized medical record. Do not use for care decisions.</span></div><header class="mv-doctor-header"><div class="eyebrow">MEDIVAULT · ${share.scope==='full'?'FULL HISTORY':'EMERGENCY SUMMARY'}</div><h1>${mvSafe(m.name)}</h1><p>${records.length} authorized fictional sample records · Expires ${mvSafe(new Date(share.expiresAt).toLocaleString())}</p><button class="btn btn-secondary" onclick="window.print()">Print this view</button></header>${share.scope==='emergency'?`<section class="mv-doctor-highlight"><h2>Emergency-relevant records</h2><p>No emergency contact or allergy is inferred. Review each linked source and confirm with the patient.</p></section>`:''}<section class="mv-doctor-records"><h2>Medical history</h2>${records.length?records.sort((a,b)=>mvIsoDate(b.date).localeCompare(mvIsoDate(a.date))).map(d=>`<article class="mv-doctor-record"><div class="eyebrow">${mvSafe(d.type)} · ${mvSafe(mvDateLabel(mvIsoDate(d.date)))}</div><h3>${mvSafe(d.title)}</h3><p>${mvSafe(d.summary||'No additional information was entered.')}</p>${d.findings?`<p>${mvSafe(d.findings)}</p>`:''}<small>Source: ${mvSafe(d.source||'User-added record')} · ${mvSafe(d.reviewState||'Not independently verified')}</small><div><button class="btn btn-secondary" data-mv-doctor-doc="${mvSafe(d.id)}" data-mv-token="${token}">Open record</button></div></article>`).join(''):'<p>No records are available in this share.'}</section><footer class="mv-doctor-footer">Extracted or unverified information may require confirmation. Sample records are fictional. This demo has no server-side access controls.</footer></main>`}
