document.addEventListener('submit',e=>{if(e.target.id==='mvAuthForm'){e.preventDefault();window.MediVaultBackend?.authSubmit(e.target)}},true);
const mvBaseShowDoc=mvShowDoc;mvShowDoc=function(id,token=''){mvBaseShowDoc(id,token);const d=docs.find(x=>x.id===id);if(!d||token)return;const actions=document.querySelector('.mv-modal-actions');if(!actions)return;const edit=document.createElement('button');edit.type='button';edit.className='btn btn-secondary';edit.textContent='Edit details';edit.onclick=()=>{openModal(`<div class="eyebrow">SOURCE-LINKED RECORD</div><h2>Edit record details</h2><p class="modal-description">Changes stay linked to the original upload. Edited information is marked for review.</p><label class="mv-field">Title<input id="mvEditTitle" value="${mvSafe(d.title)}" maxlength="140" required></label><label class="mv-field">Document date<input id="mvEditDate" type="date" value="${mvIsoDate(d.date)}" max="${mvToday()}"></label><label class="mv-field">Notes or corrected extracted text<textarea id="mvEditNotes" rows="5" maxlength="2000">${mvSafe(d.notes||d.summary||'')}</textarea></label><div class="mv-modal-actions"><button type="button" class="btn" data-dismiss>Cancel</button><button type="button" class="btn btn-primary" id="mvSaveEdit">Save changes</button></div>`);document.getElementById('mvSaveEdit').onclick=()=>{const title=document.getElementById('mvEditTitle').value.trim(),date=document.getElementById('mvEditDate').value;if(!title||!date||date>mvToday()){notify('Enter a title and valid document date.');return}d.title=title;d.date=date;d.notes=document.getElementById('mvEditNotes').value.trim();d.summary=d.notes||'No notes added.';d.status='Needs review';d.reviewState='Edited by user; review required';closeModal();render(activeView);notify('Record details saved locally; review is required.')}};actions.prepend(edit)};
function mvSearchAll(q,focus=true){mvPendingPatientSearch=q;render('vault');const field=document.getElementById('mvVaultPatientSearch');field.value=q;mvFilterPatientPicker();if(focus)field.focus()}
function mvHandleGlobalSearch(e){e.stopImmediatePropagation();const q=e.target.value.trim();if(q.length<2)return;mvSearchAll(q,false)}
document.addEventListener('input',e=>{if(e.target.id==='globalSearch')mvHandleGlobalSearch(e)},true);
filterVault=mvFilterVault;
render('overview');
const initialDoctorShare=location.hash.match(/^#doctor-share\/([A-Za-z0-9_-]+)$/);if(initialDoctorShare)mvRenderDoctorShare(initialDoctorShare[1]);
